<script setup lang="ts">
import { computed,ref } from 'vue'
import { RouterLink } from 'vue-router'
import MDialog from '@/components/ui/MDialog.vue'
import MButton from '@/components/ui/MButton.vue'
import { useCleanStore } from '@/stores/clean'
import { useCtxStore } from '@/stores/ctx'
import type { TaskRow } from '@/api/types'
const store=useCleanStore(),ctx=useCtxStore(),confirmApply=ref(false),confirmRollback=ref(false),picked=ref<TaskRow|null>(null)
const names:Record<string,string>={dedup:'重复检查',blur:'模糊检查',crop:'裁切',rotate:'旋转',mirror:'镜像'}
const canApply=computed(()=>store.previewFresh&&store.scope.length>0&&!store.applying&&!!ctx.version)
const output=computed(()=>String(store.lastApply?.version_id||store.lastApply?.version||''))
const chain=computed(()=>store.selectedOps.map(o=>names[o.name]||o.name).join('、'))
async function apply(){confirmApply.value=false;const dataset=ctx.dataset,version=ctx.version;const next=await store.apply(version,ctx.role);if(next&&ctx.dataset===dataset&&ctx.version===version){await ctx.loadVersions();ctx.setVersion(next)}}
async function rollback(){confirmRollback.value=false;const dataset=ctx.dataset;const next=await store.rollback(String(picked.value?.version_out||''));if(next&&ctx.dataset===dataset){await ctx.loadVersions();ctx.setVersion(next);picked.value=null}}
function taskTitle(row:TaskRow){const ops=row.params?.ops;return Array.isArray(ops)?ops.map(o=>typeof o==='object'&&o?names[(o as {name:string}).name]||(o as {name:string}).name:String(o)).join('、'):'图片清洗'}
const when=(t?:number)=>t?new Date(t*1000).toLocaleString('zh-CN'):''
</script>
<template><aside class="exec" aria-label="清洗执行面板"><h2>生成可继续使用的版本</h2><p>检查结果确认无误后，把保留的图片整理为新版本，再继续标注、增强或导出。</p><div class="result-count"><b>{{store.previewFresh?store.stat.kept:'—'}}</b><span>张图片将进入输出版本</span></div><p v-if="!store.previewFresh" class="hint">请先完成一次检查。更改范围或标准后，需要重新检查。</p><p v-if="store.stat.transforms&&store.previewFresh" class="hint">包含方向或裁切变换，会同时保存派生图片与对应人工标注。</p><MButton variant="primary" :disabled="!canApply" :loading="store.applying" @click="confirmApply=true">生成清洗版本</MButton><p v-if="store.applying" role="status">正在整理，请等待。离开页面不会停止后台处理，结果可在执行记录查看。</p><p v-if="store.applyError" role="alert" class="failure">{{store.applyError}}</p>
<div v-if="output===ctx.version" class="success"><b>清洗版本已生成</b><p>{{output}}</p><p>输出 {{store.lastApply?.summary?.n_kept??'—'}} 张；排除 {{store.lastApply?.summary?.n_dropped??'—'}} 张。</p><RouterLink to="/annotate">继续标注</RouterLink><RouterLink to="/augment">下一步：图像增强 →</RouterLink><RouterLink to="/export">直接导出结果</RouterLink></div>
<details class="history"><summary>执行记录与回退（{{store.history.length}}）</summary><MButton variant="ghost" size="sm" @click="store.loadHistory">刷新记录</MButton><p v-if="!store.history.length">还没有本数据集的清洗记录。</p><button v-for="row in store.history" :key="row.id" class="task" :class="{active:picked?.id===row.id}" @click="picked=picked?.id===row.id?null:row"><b>{{taskTitle(row)}}</b><span>{{when(row.created)}} · {{row.state==='done'?'已完成':row.state==='failed'?'失败':'处理中'}}</span><small>输出 {{row.version_out||'尚无版本'}}</small></button><MButton variant="danger" size="sm" :disabled="!picked?.version_out||store.rollingBack||store.applying" @click="confirmRollback=true">回退选中的这次清洗</MButton><p v-if="store.rollbackError" class="failure" role="alert">{{store.rollbackError}}</p><p v-if="store.lastRollback">已返回输入版本；回退明细：{{store.lastRollback.skipped_files||'无跳过项'}}</p></details>
<MDialog :open="confirmApply" title="确认生成清洗版本" @close="confirmApply=false"><p>本次检查 {{store.stat.total}} 张，保留 {{store.stat.kept}} 张，排除 {{store.stat.removed}} 张。</p><p>检查项目：{{chain}}。输出版本只包含本次范围的保留项。原文件和输入版本继续保留。</p><template #footer><MButton variant="ghost" @click="confirmApply=false">返回核对</MButton><MButton variant="primary" :disabled="!canApply" @click="apply">确认生成</MButton></template></MDialog>
<MDialog :open="confirmRollback" title="回退这次清洗" @close="confirmRollback=false"><p>返回这次清洗的输入版本，并清理本次产生且未被修改的派生文件。被修改的产物会保留并列出原因。</p><template #footer><MButton variant="ghost" @click="confirmRollback=false">取消</MButton><MButton variant="danger" @click="rollback">确认回退</MButton></template></MDialog></aside></template>
<style scoped>
.exec{width:285px;flex:none;border-left:1px solid var(--border);background:var(--bg-panel);padding:20px;box-sizing:border-box;overflow:auto}.exec h2{font-size:14px;margin:0 0 12px}.exec p{font-size:11px;line-height:1.8;color:var(--text-secondary);overflow-wrap:anywhere}.result-count{border:1px solid var(--border);padding:18px;border-radius:8px;margin:18px 0}.result-count>b{font:30px Consolas,monospace;display:block;margin-bottom:8px}.result-count span{font-size:11px;color:var(--text-muted)}.hint{color:var(--warning)!important}.success{border:1px solid var(--success);border-radius:7px;padding:12px;margin-top:20px}.success a{display:block;font-size:12px;color:var(--accent);margin-top:12px}.history{border-top:1px solid var(--border);margin-top:25px;padding-top:18px}.history summary{cursor:pointer;font-size:12px;margin-bottom:15px}.task{width:100%;text-align:left;background:var(--bg-raised);color:var(--text-primary);border:1px solid var(--border);padding:10px;border-radius:4px;cursor:pointer;margin:5px 0 10px}.task.active{border-color:var(--accent)}.task b,.task span,.task small{display:block;font-size:10px;margin-bottom:7px}.task span,.task small{color:var(--text-muted)}.failure{color:var(--danger)!important}
</style>
